// generated by gen_matrix (full carrier composition matrix).
use vehje_bench_carrier as c;
use mockspace_bench_core::{timed, FfiBenchCall};
use mockspace_bench_macro::bench_variant;
#[allow(unused_imports)]
use std::sync::OnceLock;

#[bench_variant("carrier_vert_tight_vert4", sizes = [64, 256, 1024, 4096, 16384])]
fn run<const N: usize>(input: &[u8; N], output: &mut [u8; 8]) -> FfiBenchCall {
    static PREP: OnceLock<c::predecode::Predecoded> = OnceLock::new(); let pd = PREP.get_or_init(|| { let mut gp = c::GenParams::profile("tight").unwrap(); gp.node_count = N; let bytes = c::ir::encode(&c::generate(&gp), &c::ir::REC24); let d = c::ir::Decoded::parse(&bytes, c::ir::REC24).unwrap(); c::predecode::predecode(&d) });
    const ITERS: usize = 16;
    timed! { run {
        let mut acc: u64 = 0;
        let mut k = 0usize;
        while k < ITERS {
            let seed = input[k % N] as u64 ^ (k as u64);
            let mut seeds = [0u64; 4]; for (l, s) in seeds.iter_mut().enumerate() { *s = seed ^ (l as u64).wrapping_mul(0x9e37_79b9); } acc ^= c::vertical::interpret_vertical_checksum::<4>(pd, &seeds);
            k += 1;
        }
        output.copy_from_slice(&acc.to_le_bytes());
    } }
}
